<?php declare(strict_types=1); namespace Modules\SEO\Controllers; use App\Http\Controllers\Controller; use App\Services\SEOService; use App\Services\SettingsService; use Core\Http\RedirectResponse; use Core\Http\Request; use Core\Http\Response; class SeoController extends Controller { public function __construct( private readonly SettingsService $settings, private readonly SEOService $seo, ) { } public function index(): Response { $defaults = (array) config('seo.defaults', []); return $this->view('seo::Admin.index', [ 'title' => trans('common.seo'), 'seo' => array_merge($defaults, (array) $this->settings->get('seo_defaults', [])), ]); } public function update(Request $request): RedirectResponse { $data = $request->validate([ 'title' => 'required|string|max:255', 'description' => 'required|string|max:255', 'keywords' => 'nullable|string|max:255', ]); $data['keywords'] = array_map('trim', explode(',', (string) ($data['keywords'] ?? ''))); $this->settings->set('seo_defaults', $data, auth()->id()); return $this->redirect(route('admin.seo.index')) ->with('_success', trans('common.saved')); } } 